function historyOpenAllowed(record,type){if(!unresolved())return true;const active=getStored(activeCheckKey);return type==='check'&&record.state!=='COMPLETED'&&validActive(active)&&active.id===record.id;}
function historyCard(record,type){const item=node('article',undefined,'history-item'),title=type==='check'?(record.report?.verdict??record.state??'Kontrol'):(record.status??'Politika'),mode=type==='check'?(record.mode==='REPLAY'?'Kayıtlı örnek':record.source==='AGENT'?'Ajan incelemesi':'Canlı kontrol'):'Politika';item.append(node('strong',title),node('span',mode+' · '+safeTime(historyTime(record))),node('span',String(record.id??'').slice(0,12)));if(type==='check'&&record.report?.candidate)item.append(node('span',record.report.candidate.price+' USDT/AVAX · '+record.report.candidate.size+' AVAX'));if(uuid(record.id)){const label=type==='check'?(record.state==='COMPLETED'?'Raporu aç':'Kontrolü izle'):'Politikayı aç',open=node('button',label,'text-command');open.type='button';open.setAttribute('aria-label',`${label}: ${title}, ${mode}, ${safeTime(historyTime(record))}`);open.disabled=!historyOpenAllowed(record,type);historyOpenButtons.push({button:open,record,type});open.addEventListener('click',()=>{if(!historyOpenAllowed(record,type))return;if(type==='check')void getCheck(record.id,{poll:record.state!=='COMPLETED',selectResult:true}).catch(error=>{if(!error.stale&&error.status!==401)showError(error.message);});else void api('/api/preflight/policies/'+encodeURIComponent(record.id)).then(fetched=>{if(renderPolicy(fetched)){selectMode('live',{force:true});selectLiveStep('policy',{force:true,focus:true});}}).catch(error=>{if(!error.stale&&error.status!==401)showError(error.message);});});item.append(open);}return item;}
async function loadHistory({recoverActive=true}={}){const epoch=sessionEpoch,history=await api('/api/preflight/history');if(epoch!==sessionEpoch)return;if(!exactKeys(history,['policies','checks'])||!Array.isArray(history.policies)||!Array.isArray(history.checks))throw new Error('Geçmiş kaydı doğrulanamadı.');const recovered=policyCreationUncertain?history.policies.find(item=>uuid(item.id)&&!knownPolicyIds.has(item.id)):null,records=[...history.checks.map(value=>({value,type:'check'})),...history.policies.map(value=>({value,type:'policy'}))].sort((a,b)=>(historyTime(b.value)??0)-(historyTime(a.value)??0));$('#history-empty').hidden=records.length!==0;if(currentMode==='history')$('#history-section').hidden=false;historyOpenButtons=[];$('#history-list').replaceChildren(...records.map(({value,type})=>historyCard(value,type)));if(!policy){const latest=recovered??(!policyCreationUncertain?history.policies[0]:null);if(latest&&uuid(latest.id))try{const fetched=await api('/api/preflight/policies/'+encodeURIComponent(latest.id));if(epoch!==sessionEpoch)return;if(renderPolicy(fetched)){policyCreationUncertain=false;if(recovered)removeStored(policyPendingKey);}}catch(error){if(error.status===401||error.stale||epoch!==sessionEpoch)return;}}if(epoch!==sessionEpoch)return;if(policyCreationUncertain&&!recovered)text($('#policy-message'),'Oluşturma sonucu hâlâ bulunamadı. Yeni politika açılmadı; kayıtları yeniden kontrol et.');for(const item of history.policies)if(uuid(item.id))knownPolicyIds.add(item.id);syncControls();const active=getStored(activeCheckKey);if(recoverActive&&validActive(active)&&!activeCheck)getCheck(active.id,{poll:true,refreshHistory:false,selectResult:true}).catch(error=>{if(!error.stale&&error.status!==401)showPollRecovery(error.message);});}
function restoreStoredState(){let discarded=false;for(const [key,valid] of [[pendingKey,validPending],[activeCheckKey,validActive],[policyPendingKey,validPolicyPending]]){const value=getStored(key);if(value&&!valid(value)){removeStored(key);discarded=true;}}const creation=getStored(policyPendingKey);policyCreationUncertain=validPolicyPending(creation);if(policyCreationUncertain){for(const id of creation.knownPolicyIds)knownPolicyIds.add(id);$('#policy-uncertain').hidden=false;}if(discarded)showError('Önceki oturuma ait doğrulanmamış istekler yeni çalışma alanına taşınmadı.');}
async function enter(){const epoch=++sessionEpoch;$('#boot-error').hidden=true;try{const boot=await api('/api/bootstrap');if(epoch!==sessionEpoch)return;if(typeof boot.csrf!=='string'||!boot.csrf)throw new Error('Oturum anahtarı doğrulanamadı.');csrf=boot.csrf;sessionMarker=await bindSession(csrf);restoreStoredState();const [nextStatus]=await Promise.all([api('/api/preflight/status'),loadHistory()]);if(epoch!==sessionEpoch)return;renderStatus(nextStatus);$('#access').hidden=true;const pending=getStored(pendingKey),active=getStored(activeCheckKey);if(validPending(pending))showUncertain();else if(validActive(active))showResultSurface(active);else if(currentReport?.report){if(currentReport.report.mode==='LIVE_READ_ONLY')currentStep='result';selectMode(currentReport.report.mode==='REPLAY'?'examples':'live',{force:true});}else{selectMode('live',{force:true});selectLiveStep(policyCreationUncertain||approvalUncertain||!currentPolicy()?'policy':'candidate',{force:true});}connection(true);}catch(error){if(error.status!==401&&epoch===sessionEpoch)showBootError(error.message);}}
$('#policy-form').addEventListener('submit',async event=>{event.preventDefault();if(unresolved())return;selectMode('live',{force:true});selectLiveStep('policy',{force:true});if(policy||!validatePolicyForm())return;setBusy(true);text($('#policy-message'),'Politika özeti hazırlanıyor.');const epoch=sessionEpoch,marker={knownPolicyIds:[...knownPolicyIds],startedAtMs:Date.now(),sessionBinding:sessionMarker};if(!setStored(policyPendingKey,marker)){showError('Politika isteği tarayıcıda güvenle izlenemedi; istek gönderilmedi.');setBusy(false);return;}try{const result=await api('/api/preflight/policies',{method:'POST',body:policyBody()});if(epoch!==sessionEpoch)return;if(!renderPolicy(result))throw new Error('Politika kaydı doğrulanamadı.');removeStored(policyPendingKey);text($('#policy-message'),'Sınırları inceleyip onayla.');await loadHistory();}catch(error){if(error.status===401||epoch!==sessionEpoch)return;if(error.unconfirmed){policyCreationUncertain=true;selectMode('live',{force:true});selectLiveStep('policy',{force:true});$('#policy-uncertain').hidden=false;}else removeStored(policyPendingKey);showError(error.unconfirmed?'Politika oluşturma sonucu bilinmiyor. Yeni politika oluşturmadan kayıtları yenile.':error.message);}finally{if(epoch===sessionEpoch)setBusy(false);}});
$('#policy-form').addEventListener('input',event=>{markReportStale();if(event.target?.id)setFieldError(event.target.id,'');});$('#candidate-form').addEventListener('input',event=>{markReportStale();if(event.target?.id)setFieldError(event.target.id,'');updateCandidatePreview();});$('#policy-ack').addEventListener('change',syncControls);
$('#mode-agent').addEventListener('change',()=>{if($('#mode-agent').checked&&agentCapable()){checkMode='agent';syncControls();}});$('#mode-direct').addEventListener('change',()=>{if($('#mode-direct').checked){checkMode='direct';syncControls();}});
$('#approve-policy').addEventListener('click',async()=>{if(unresolved()||!policy||!$('#policy-ack').checked)return;setBusy(true);const epoch=sessionEpoch;try{const result=await api('/api/preflight/policies/'+encodeURIComponent(policy.id)+'/approve',{method:'POST',body:{policyHash:policy.policyHash,acknowledgement:true}});if(epoch!==sessionEpoch)return;if(!renderPolicy(result))throw new Error('Politika kaydı doğrulanamadı.');text($('#policy-message'),'Politika onaylandı ve değişmez olarak kaydedildi.');await loadHistory();selectMode('live',{force:true});selectLiveStep(currentPolicy()?'candidate':'policy',{force:true,focus:true});}catch(error){if(error.status===401||epoch!==sessionEpoch)return;if(error.unconfirmed){approvalUncertain=true;selectMode('live',{force:true});selectLiveStep('policy',{force:true});$('#approval-uncertain').hidden=false;showError('Onay sonucu bilinmiyor. Politikayı yeniden okuyarak doğrula.');}else showError(error.message);}finally{if(epoch===sessionEpoch)setBusy(false);}});
$('#retry-approval').addEventListener('click',async()=>{if(busy||!approvalUncertain||!policy)return;setBusy(true);const epoch=sessionEpoch,id=policy.id,policyHash=policy.policyHash;try{let latest=await api('/api/preflight/policies/'+encodeURIComponent(id));if(epoch!==sessionEpoch)return;if(latest.status!=='APPROVED')latest=await api('/api/preflight/policies/'+encodeURIComponent(id)+'/approve',{method:'POST',body:{policyHash,acknowledgement:true}});if(epoch!==sessionEpoch)return;if(!renderPolicy(latest))throw new Error('Politika kaydı doğrulanamadı.');text($('#policy-message'),'Onay sonucu doğrulandı.');await loadHistory();selectMode('live',{force:true});selectLiveStep(currentPolicy()?'candidate':'policy',{force:true,focus:true});}catch(error){if(error.status!==401&&epoch===sessionEpoch)showError(error.unconfirmed?'Onay sonucu hâlâ doğrulanamadı. Aynı politikayı yeniden kontrol et.':error.message);}finally{if(epoch===sessionEpoch)setBusy(false);}});
$('#replace-policy').addEventListener('click',resetPolicy);
$('#candidate-form').addEventListener('submit',event=>{event.preventDefault();if(unresolved())return;selectMode('live',{force:true});if(!currentPolicy()){updatePolicyExpiry();selectLiveStep('policy',{force:true});showError('Politikanın süresi doldu. Yeni politika oluşturarak devam et.');$('#replace-policy').focus();return;}selectLiveStep('candidate',{force:true});if(!validateCandidateForm())return;const path=checkMode==='agent'&&agentCapable()?'/api/preflight/agent-checks':'/api/preflight/checks';void submitStable(path,{policyId:policy.id,policyHash:policy.policyHash,candidate:candidateBody(),clientRequestId:requestId()});});
for(const button of document.querySelectorAll('[data-example]'))button.addEventListener('click',()=>{if(unresolved())return;void submitStable('/api/preflight/examples/'+encodeURIComponent(button.dataset.example),{clientRequestId:requestId()});});
$('#retry-pending').addEventListener('click',()=>{const pending=getStored(pendingKey);if(validPending(pending)&&!busy)void submitStable(pending.path,pending.body);});$('#retry-poll').addEventListener('click',()=>{const active=getStored(activeCheckKey);if(!validActive(active)||busy)return;setBusy(true);const epoch=sessionEpoch;void getCheck(active.id,{poll:true,selectResult:true}).catch(error=>{if(!error.stale&&error.status!==401&&epoch===sessionEpoch)showPollRecovery(error.message);}).finally(()=>{if(epoch===sessionEpoch)setBusy(false);});});
$('#reconcile-policy').addEventListener('click',async()=>{try{await loadHistory();const marker=getStored(policyPendingKey);if(policyCreationUncertain&&validPolicyPending(marker)&&Date.now()-marker.startedAtMs>=10000)$('#abandon-policy').hidden=false;}catch(error){if(!error.stale&&error.status!==401)showError(error.message);}});$('#abandon-policy').addEventListener('click',()=>{removeStored(policyPendingKey);policyCreationUncertain=false;$('#policy-uncertain').hidden=true;text($('#policy-message'),'Önceki sonuç bırakıldı. Geç gelirse yalnız onaysız bir taslak olarak kalır.');syncControls();});
$('#download-report').addEventListener('click',async()=>{if(!currentReport?.checkId||busy)return;setBusy(true);const epoch=sessionEpoch;try{const report=await api('/api/preflight/checks/'+encodeURIComponent(currentReport.checkId)+'/report');if(epoch!==sessionEpoch)return;if(!validReport(report))throw new Error('Rapor biçimi doğrulanamadı.');const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'})),link=node('a');link.href=url;link.download='pactway-preflight-'+currentReport.checkId+'.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){if(error.status!==401&&epoch===sessionEpoch)showError(error.message);}finally{if(epoch===sessionEpoch)setBusy(false);}});
$('#refresh-history').addEventListener('click',async()=>{if(busy)return;setBusy(true);const epoch=sessionEpoch;try{await Promise.all([loadHistory(),refreshStatus()]);}catch(error){if(error.status!==401&&epoch===sessionEpoch)showError(error.message);}finally{if(epoch===sessionEpoch)setBusy(false);}});$('#refresh-status').addEventListener('click',()=>{if(!busy)void refreshStatus();});$('#retry-startup').addEventListener('click',()=>void enter());$('#dismiss-error').addEventListener('click',clearError);$('#view-live').addEventListener('click',()=>selectMode('live'));$('#view-examples').addEventListener('click',()=>selectMode('examples'));$('#view-history').addEventListener('click',()=>selectMode('history'));$('#return-live').addEventListener('click',()=>{if(!selectMode('live'))return;selectLiveStep(lastLiveReport?'result':currentPolicy()?'candidate':'policy',{force:true});});
for(const step of ['policy','candidate','result'])$('#step-'+step).addEventListener('click',()=>selectLiveStep(step,{focus:true}));
$('#edit-candidate').addEventListener('click',()=>{if(selectMode('live')&&selectLiveStep('candidate',{focus:true}))updateCandidatePreview();});
