$('#join').addEventListener('click',async()=>{if(busy)return;const inviteCode=$('#invite-code').value;if(inviteRequired&&!validInviteCode(inviteCode)){text($('#invite-code-error'),'Davet kodu 24–256 karakter olmalı.');$('#invite-code-error').hidden=false;attr($('#invite-code'),'aria-invalid','true');$('#invite-code').focus();return;}setBusy(true);text($('#access-error'),'');const epoch=sessionEpoch,body=inviteRequired?{inviteCode}:{};$('#invite-code').value='';try{const boot=await api('/api/session/join',{method:'POST',body});if(epoch!==sessionEpoch)return;if(typeof boot.csrf!=='string'||!boot.csrf)throw new Error('Oturum açılamadı.');csrf=boot.csrf;setBusy(false);await enter();}catch(error){if(error.status!==401&&epoch===sessionEpoch)text($('#access-error'),error.message);}finally{if(epoch===sessionEpoch)setBusy(false);}});

